def _assert_downgrade_safe() -> None:
    allowed = ", ".join(
        f"'{name}'" for name in (*_PRE_0030_RELATIONS, *(t.name for t in _DECISION_TABLES))
    )
    op.execute(
        f"""
DO $v2_wp03_preflight$
DECLARE unknown_objects text;
BEGIN
    SELECT string_agg(c.relname, ', ' ORDER BY c.relname)
      INTO unknown_objects
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'trading'
       AND c.relkind IN ('r','p','v','m','f')
       AND c.relname NOT IN ({allowed})
       AND NOT EXISTS (
           SELECT 1 FROM pg_inherits i
           JOIN pg_class p ON p.oid = i.inhparent
           JOIN pg_namespace pn ON pn.oid = p.relnamespace
           WHERE i.inhrelid = c.oid AND pn.nspname = 'trading'
             AND ((p.relname = 'outbox_delivery_history'
                   AND c.relname ~ '^outbox_delivery_history_[0-9]{{6}}$')
               OR (p.relname IN ('pm_source_event_batches','pm_source_event_index',
                                  'pm_book_checkpoints','pm_book_levels')
                   AND c.relname ~ ('^' || p.relname || '_[0-9]{{8}}$'))
               OR (p.relname IN ('ai_invocations','ai_tool_calls','ai_validation_results')
                   AND c.relname ~ ('^' || p.relname || '_[0-9]{{6}}$')))
       );
    IF unknown_objects IS NOT NULL THEN
        RAISE EXCEPTION 'v2_wp03_unknown_object:%', unknown_objects USING ERRCODE='55000';
    END IF;
END $v2_wp03_preflight$
"""
    )


def _reinforce_existing() -> None:
    """pm_quote_bindings / gate_decisions / information_snapshots / forecast_episodes 强化。"""
    # pm_quote_bindings：加 trade_decision_id；删旧唯一；加 partial unique index。
    op.execute("ALTER TABLE trading.pm_quote_bindings ADD COLUMN trade_decision_id BIGINT")
    op.execute(
        "ALTER TABLE trading.pm_quote_bindings ADD CONSTRAINT fk_pm_quote_bindings_trade_decision "
        "FOREIGN KEY(trade_decision_id) REFERENCES trading.trade_decisions (id)"
    )
    op.execute(
        "ALTER TABLE trading.pm_quote_bindings "
        "DROP CONSTRAINT IF EXISTS uq_pm_quote_bindings_token_checkpoint"
    )
    op.execute(
        "CREATE UNIQUE INDEX uq_pm_quote_bindings_decision_token "
        "ON trading.pm_quote_bindings (trade_decision_id, token_id) "
        "WHERE trade_decision_id IS NOT NULL"
    )
    # gate_decisions：G7A/G7B + trade_decision target
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        "DROP CONSTRAINT IF EXISTS ck_gate_decisions_gate_known"
    )
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        f"ADD CONSTRAINT ck_gate_decisions_gate_known CHECK (gate IN ({_GATE_VALUES}))"
    )
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        "DROP CONSTRAINT IF EXISTS ck_gate_decisions_target_kind_known"
    )
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        "ADD CONSTRAINT ck_gate_decisions_target_kind_known CHECK ("
        "target_kind IN ('screening','opportunity','episode','trade_decision'))"
    )
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        "DROP CONSTRAINT IF EXISTS ck_gate_decisions_gate_target_pair"
    )
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        "ADD CONSTRAINT ck_gate_decisions_gate_target_pair CHECK ("
        "(gate IN ('G0','R0') AND target_kind = 'screening') OR "
        "(gate IN ('G1','G2') AND target_kind = 'opportunity') OR "
        "(gate IN ('R1','G4','G5A','G5B','G6') AND target_kind = 'episode') OR "
        "(gate IN ('G7A','G7B') AND target_kind = 'trade_decision'))"
    )
    # information_snapshots：G7A/G7B + trade_decision_id 目标
    op.execute(
        "ALTER TABLE trading.information_snapshots "
        "DROP CONSTRAINT IF EXISTS ck_information_snapshots_gate_known"
    )
    op.execute(
        "ALTER TABLE trading.information_snapshots "
        f"ADD CONSTRAINT ck_information_snapshots_gate_known CHECK (gate IN ({_GATE_VALUES}))"
    )
    op.execute("ALTER TABLE trading.information_snapshots ADD COLUMN trade_decision_id BIGINT")
    op.execute(
        "ALTER TABLE trading.information_snapshots ADD CONSTRAINT fk_information_snapshots_trade_decision "
        "FOREIGN KEY(trade_decision_id) REFERENCES trading.trade_decisions (id)"
    )
    op.execute(
        "ALTER TABLE trading.information_snapshots "
        "DROP CONSTRAINT IF EXISTS ck_information_snapshots_one_target"
    )
    op.execute(
        "ALTER TABLE trading.information_snapshots "
        "ADD CONSTRAINT ck_information_snapshots_one_target CHECK ("
        "(episode_id IS NOT NULL)::int + (opportunity_id IS NOT NULL)::int "
        "+ (trade_decision_id IS NOT NULL)::int = 1)"
    )
    # forecast_episodes：REVEALED/DECIDED
    op.execute(
        "ALTER TABLE trading.forecast_episodes "
        "DROP CONSTRAINT IF EXISTS ck_forecast_episodes_status_known"
    )
    op.execute(
        "ALTER TABLE trading.forecast_episodes "
        "ADD CONSTRAINT ck_forecast_episodes_status_known CHECK ("
        "status IN ('DRAFT','ROUTED','BLIND_COMMITTED','REVEALED','DECIDED','PRE_COMMIT_TERMINAL'))"
    )


def _unreinforce_existing() -> None:
    """撤销强化并恢复 b1000021 原约束。"""
    op.execute(
        "ALTER TABLE trading.forecast_episodes "
        "DROP CONSTRAINT IF EXISTS ck_forecast_episodes_status_known"
    )
    op.execute(
        "ALTER TABLE trading.forecast_episodes "
        "ADD CONSTRAINT ck_forecast_episodes_status_known CHECK ("
        "status IN ('DRAFT','ROUTED','BLIND_COMMITTED','PRE_COMMIT_TERMINAL'))"
    )
    op.execute(
        "ALTER TABLE trading.information_snapshots "
        "DROP CONSTRAINT IF EXISTS ck_information_snapshots_one_target"
    )
    op.execute(
        "ALTER TABLE trading.information_snapshots "
        "ADD CONSTRAINT ck_information_snapshots_one_target CHECK ("
        "(episode_id IS NULL) <> (opportunity_id IS NULL))"
    )
    op.execute(
        "ALTER TABLE trading.information_snapshots "
        "DROP CONSTRAINT IF EXISTS fk_information_snapshots_trade_decision"
    )
    op.execute("ALTER TABLE trading.information_snapshots DROP COLUMN IF EXISTS trade_decision_id")
    op.execute(
        "ALTER TABLE trading.information_snapshots "
        "DROP CONSTRAINT IF EXISTS ck_information_snapshots_gate_known"
    )
    op.execute(
        "ALTER TABLE trading.information_snapshots "
        "ADD CONSTRAINT ck_information_snapshots_gate_known CHECK ("
        "gate IN ('G0','R0','G1','G2','R1','G4','G5A','G5B','G6'))"
    )
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        "DROP CONSTRAINT IF EXISTS ck_gate_decisions_gate_target_pair"
    )
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        "ADD CONSTRAINT ck_gate_decisions_gate_target_pair CHECK ("
        "(gate IN ('G0','R0') AND target_kind = 'screening') OR "
        "(gate IN ('G1','G2') AND target_kind = 'opportunity') OR "
        "(gate IN ('R1','G4','G5A','G5B','G6') AND target_kind = 'episode'))"
    )
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        "DROP CONSTRAINT IF EXISTS ck_gate_decisions_target_kind_known"
    )
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        "ADD CONSTRAINT ck_gate_decisions_target_kind_known CHECK ("
        "target_kind IN ('screening','opportunity','episode'))"
    )
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        "DROP CONSTRAINT IF EXISTS ck_gate_decisions_gate_known"
    )
    op.execute(
        "ALTER TABLE trading.gate_decisions "
        "ADD CONSTRAINT ck_gate_decisions_gate_known CHECK ("
        "gate IN ('G0','R0','G1','G2','R1','G4','G5A','G5B','G6'))"
    )
    op.execute("DROP INDEX IF EXISTS uq_pm_quote_bindings_decision_token")
    op.execute(
        "ALTER TABLE trading.pm_quote_bindings "
        "ADD CONSTRAINT uq_pm_quote_bindings_token_checkpoint "
        "UNIQUE (token_id, checkpoint_id, checkpoint_received_at)"
    )
    op.execute(
        "ALTER TABLE trading.pm_quote_bindings "
        "DROP CONSTRAINT IF EXISTS fk_pm_quote_bindings_trade_decision"
    )
    op.execute("ALTER TABLE trading.pm_quote_bindings DROP COLUMN IF EXISTS trade_decision_id")


def _gate_guard_fn() -> str:
    return r"""
CREATE FUNCTION trading.v2_guard_gate_decision() RETURNS trigger
LANGUAGE plpgsql AS $v2_guard$
DECLARE
    root_id bigint;
    screening_id bigint;
    opportunity_id bigint;
BEGIN
    IF NEW.gate IN ('G0','R0') THEN
        IF NOT EXISTS (SELECT 1 FROM trading.screening_episodes WHERE id = NEW.target_id) THEN
            RAISE EXCEPTION 'v2_gate_target_missing' USING ERRCODE='23503';
        END IF;
    ELSIF NEW.gate IN ('G1','G2') THEN
        IF NOT EXISTS (SELECT 1 FROM trading.decision_opportunities WHERE id = NEW.target_id) THEN
            RAISE EXCEPTION 'v2_gate_target_missing' USING ERRCODE='23503';
        END IF;
    ELSIF NEW.gate IN ('G7A','G7B') THEN
        IF NOT EXISTS (SELECT 1 FROM trading.trade_decisions WHERE id = NEW.target_id) THEN
            RAISE EXCEPTION 'v2_gate_target_missing' USING ERRCODE='23503';
        END IF;
    ELSIF NOT EXISTS (SELECT 1 FROM trading.forecast_episodes WHERE id = NEW.target_id) THEN
        RAISE EXCEPTION 'v2_gate_target_missing' USING ERRCODE='23503';
    END IF;

    IF (NEW.gate = 'G0' AND NEW.result NOT IN ('PASS','PREDICTION_RESEARCH_ONLY'))
       OR (NEW.gate = 'R0' AND NEW.result NOT IN ('SELECT','DEFER','REJECT'))
       OR (NEW.gate IN ('G1','G2') AND NEW.result NOT IN ('PASS','FAIL'))
       OR (NEW.gate = 'R1' AND NEW.result NOT IN ('reject','shallow','standard','deep'))
       OR (NEW.gate = 'G4' AND NEW.result NOT IN ('PASS','FAIL'))
       OR (NEW.gate = 'G5A' AND NEW.result NOT IN ('PASS','ABSTAIN_EVIDENCE_INTEGRITY'))
       OR (NEW.gate = 'G5B' AND NEW.result NOT IN ('PASS','WIDEN_REQUIRED','ABSTAIN_EVIDENCE_INSUFFICIENT'))
       OR (NEW.gate IN ('G6','G7A','G7B') AND NEW.result NOT IN ('PASS','FAIL')) THEN
        RAISE EXCEPTION 'v2_gate_result_invalid' USING ERRCODE='23514';
    END IF;
    IF NEW.result IN ('PREDICTION_RESEARCH_ONLY','DEFER','REJECT','FAIL',
                      'ABSTAIN_EVIDENCE_INTEGRITY','WIDEN_REQUIRED','ABSTAIN_EVIDENCE_INSUFFICIENT','reject')
       AND NEW.reason_code IS NULL THEN
        RAISE EXCEPTION 'v2_gate_failure_reason_required' USING ERRCODE='23514';
    END IF;

    IF NEW.gate = 'R0' AND NOT EXISTS (
        SELECT 1 FROM trading.gate_decisions gd
         WHERE gd.gate = 'G0' AND gd.target_kind = 'screening'
           AND gd.target_id = NEW.target_id AND gd.result = 'PASS'
    ) THEN
        RAISE EXCEPTION 'v2_gate_order_g0_r0' USING ERRCODE='23514';
    ELSIF NEW.gate = 'G1' THEN
        SELECT COALESCE(o.parent_id, o.id) INTO STRICT root_id
          FROM trading.decision_opportunities o WHERE o.id = NEW.target_id;
        SELECT source_screening_episode_id INTO screening_id
          FROM trading.decision_opportunities WHERE id = root_id;
        IF screening_id IS NULL OR NOT EXISTS (
            SELECT 1 FROM trading.gate_decisions gd
             WHERE gd.gate = 'R0' AND gd.target_kind = 'screening'
               AND gd.target_id = screening_id
               AND (gd.result = 'SELECT' OR EXISTS (
                    SELECT 1 FROM trading.screening_episodes se
                     WHERE se.id = screening_id AND se.audit_assigned))
        ) THEN
            RAISE EXCEPTION 'v2_gate_order_r0_g1' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.gate = 'G2' THEN
        SELECT COALESCE(o.parent_id, o.id) INTO STRICT root_id
          FROM trading.decision_opportunities o WHERE o.id = NEW.target_id;
        IF NOT EXISTS (
            SELECT 1 FROM trading.gate_decisions gd
            JOIN trading.decision_opportunities prior ON prior.id = gd.target_id
             WHERE gd.gate = 'G1' AND gd.target_kind = 'opportunity' AND gd.result = 'PASS'
               AND COALESCE(prior.parent_id, prior.id) = root_id
        ) THEN
            RAISE EXCEPTION 'v2_gate_order_g1_g2' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.gate = 'R1' THEN
        SELECT decision_opportunity_id INTO STRICT opportunity_id
          FROM trading.forecast_episodes WHERE id = NEW.target_id;
        IF NOT EXISTS (
            SELECT 1 FROM trading.gate_decisions gd
             WHERE gd.gate = 'G2' AND gd.target_kind = 'opportunity'
               AND gd.target_id = opportunity_id AND gd.result = 'PASS'
        ) THEN
            RAISE EXCEPTION 'v2_gate_order_g2_r1' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.gate = 'G4' THEN
        IF NOT EXISTS (
            SELECT 1 FROM trading.gate_decisions gd
             WHERE gd.gate = 'R1' AND gd.target_kind = 'episode'
               AND gd.target_id = NEW.target_id
               AND gd.result IN ('shallow','standard','deep')
        ) THEN
            RAISE EXCEPTION 'v2_gate_order_r1_g4' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.gate = 'G5A' THEN
        IF NOT EXISTS (
            SELECT 1 FROM trading.gate_decisions gd
             WHERE gd.gate = 'G4' AND gd.target_kind = 'episode'
               AND gd.target_id = NEW.target_id AND gd.result = 'PASS'
        ) THEN
            RAISE EXCEPTION 'v2_gate_order_g4_g5a' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.gate = 'G5B' THEN
        IF NOT EXISTS (
            SELECT 1 FROM trading.gate_decisions gd
             WHERE gd.gate = 'G5A' AND gd.target_kind = 'episode'
               AND gd.target_id = NEW.target_id AND gd.result = 'PASS'
        ) THEN
            RAISE EXCEPTION 'v2_gate_order_g5a_g5b' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.gate = 'G6' THEN
        IF NOT EXISTS (
            SELECT 1 FROM trading.gate_decisions gd
             WHERE gd.gate = 'G5B' AND gd.target_kind = 'episode'
               AND gd.target_id = NEW.target_id AND gd.result = 'PASS'
        ) THEN
            RAISE EXCEPTION 'v2_gate_order_g5b_g6' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.gate = 'G7B' THEN
        IF NOT EXISTS (
            SELECT 1 FROM trading.gate_decisions gd
             WHERE gd.gate = 'G7A' AND gd.target_kind = 'trade_decision'
               AND gd.target_id = NEW.target_id AND gd.result = 'PASS'
        ) THEN
            RAISE EXCEPTION 'v2_gate_order_g7a_g7b' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END $v2_guard$
"""


def _create_guards() -> None:
    for table in _DECISION_TABLES:
        if table.append_only:
            op.execute(
                f"CREATE TRIGGER trg_{table.name}_immutable "
                f"BEFORE UPDATE OR DELETE ON {TRADING_SCHEMA}.{table.name} "
                "FOR EACH ROW EXECUTE FUNCTION trading.v2_reject_immutable_row()"
            )
    # 替换 gate guard（G7A/G7B target + order）
    op.execute("DROP TRIGGER IF EXISTS trg_gate_decisions_semantics ON trading.gate_decisions")
    op.execute("DROP FUNCTION IF EXISTS trading.v2_guard_gate_decision()")
    op.execute(_gate_guard_fn())
    op.execute(
        "CREATE TRIGGER trg_gate_decisions_semantics BEFORE INSERT ON trading.gate_decisions "
        "FOR EACH ROW EXECUTE FUNCTION trading.v2_guard_gate_decision()"
    )
    # trade_decisions 生命周期 guard
    op.execute(
        r"""
CREATE FUNCTION trading.v2_guard_trade_decision() RETURNS trigger
LANGUAGE plpgsql AS $v2_guard$
DECLARE terminal text[] := ARRAY['ACTION','WAIT','ABSTAIN'];
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'v2_trade_decision_immutable' USING ERRCODE='55000';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'CREATED' OR NEW.quote_bound_at IS NOT NULL
           OR NEW.decided_at IS NOT NULL OR NEW.output_hash IS NOT NULL THEN
            RAISE EXCEPTION 'v2_trade_decision_initial_state_invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.decision_key IS DISTINCT FROM NEW.decision_key
       OR OLD.episode_id IS DISTINCT FROM NEW.episode_id
       OR OLD.forecast_submission_id IS DISTINCT FROM NEW.forecast_submission_id
       OR OLD.objective_contract_id IS DISTINCT FROM NEW.objective_contract_id
       OR OLD.strategy_version_id IS DISTINCT FROM NEW.strategy_version_id
       OR OLD.release_manifest_id IS DISTINCT FROM NEW.release_manifest_id
       OR OLD.execution_spec_version_id IS DISTINCT FROM NEW.execution_spec_version_id
       OR OLD.capital_permission_manifest_id IS DISTINCT FROM NEW.capital_permission_manifest_id
       OR OLD.experiment_variant IS DISTINCT FROM NEW.experiment_variant
       OR OLD.trigger_at IS DISTINCT FROM NEW.trigger_at
       OR OLD.input_hash IS DISTINCT FROM NEW.input_hash
       OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN
        RAISE EXCEPTION 'v2_trade_decision_identity_immutable' USING ERRCODE='55000';
    END IF;
    -- terminal 后禁改
    IF OLD.status = ANY(terminal) AND NEW.status IS DISTINCT FROM OLD.status THEN
        RAISE EXCEPTION 'v2_trade_decision_terminal_immutable' USING ERRCODE='55000';
    END IF;
    -- 状态机
    IF OLD.status = 'CREATED' AND NEW.status = 'QUOTE_BOUND' AND NEW.quote_bound_at IS NOT NULL
       AND NEW.decided_at IS NULL THEN
        RETURN NEW;
    ELSIF OLD.status = 'QUOTE_BOUND' AND NEW.status = 'G7A' AND NEW.decided_at IS NULL THEN
        RETURN NEW;
    ELSIF OLD.status = 'G7A' AND NEW.status = 'G7B' AND NEW.decided_at IS NULL THEN
        RETURN NEW;
    ELSIF OLD.status = 'G7B' AND NEW.status = ANY(terminal)
          AND NEW.decided_at IS NOT NULL AND NEW.output_hash IS NOT NULL THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'v2_trade_decision_immutable' USING ERRCODE='55000';
END $v2_guard$
"""
    )
    op.execute(
        "CREATE TRIGGER trg_trade_decisions_lifecycle "
        "BEFORE INSERT OR UPDATE OR DELETE ON trading.trade_decisions "
        "FOR EACH ROW EXECUTE FUNCTION trading.v2_guard_trade_decision()"
    )
    # action_sets：ACTION 必须至少 1 leg，WAIT/ABSTAIN 无 leg（deferred 核验）
    op.execute(
        r"""
CREATE FUNCTION trading.v2_check_action_set() RETURNS trigger
LANGUAGE plpgsql AS $v2_guard$
DECLARE
    set_ref bigint;
    leg_count integer;
    set_disposition text;
BEGIN
    IF TG_TABLE_NAME = 'action_sets' THEN
        set_ref := NEW.id;
    ELSE
        set_ref := NEW.action_set_id;
    END IF;
    SELECT disposition INTO STRICT set_disposition
      FROM trading.action_sets WHERE id = set_ref;
    IF set_disposition = 'ACTION' THEN
        SELECT count(*) INTO leg_count FROM trading.action_set_legs WHERE action_set_id = set_ref;
        IF leg_count = 0 THEN
            RAISE EXCEPTION 'v2_action_set_action_requires_leg' USING ERRCODE='23514';
        END IF;
    ELSIF set_disposition IN ('WAIT','ABSTAIN') THEN
        IF EXISTS (SELECT 1 FROM trading.action_set_legs WHERE action_set_id = set_ref) THEN
            RAISE EXCEPTION 'v2_action_set_wait_abstain_no_leg' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END $v2_guard$
"""
    )
    for table, events in (("action_sets", "INSERT"), ("action_set_legs", "INSERT OR UPDATE")):
        op.execute(
            f"CREATE CONSTRAINT TRIGGER trg_{table}_action_set_complete "
            f"AFTER {events} ON trading.{table} "
            "DEFERRABLE INITIALLY DEFERRED FOR EACH ROW "
            "EXECUTE FUNCTION trading.v2_check_action_set()"
        )
    # economic_action_intents：PLANNED→COMMITTED|SUPERSEDED；terminal 禁改
    op.execute(
        r"""
CREATE FUNCTION trading.v2_guard_action_intent() RETURNS trigger
LANGUAGE plpgsql AS $v2_guard$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'v2_action_intent_immutable' USING ERRCODE='55000';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'PLANNED' THEN
            RAISE EXCEPTION 'v2_action_intent_initial_state_invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.intent_key IS DISTINCT FROM NEW.intent_key
       OR OLD.intent_hash IS DISTINCT FROM NEW.intent_hash
       OR OLD.trade_decision_id IS DISTINCT FROM NEW.trade_decision_id
       OR OLD.action_set_id IS DISTINCT FROM NEW.action_set_id
       OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN
        RAISE EXCEPTION 'v2_action_intent_identity_immutable' USING ERRCODE='55000';
    END IF;
    IF OLD.status IN ('COMMITTED','SUPERSEDED') AND NEW.status IS DISTINCT FROM OLD.status THEN
        RAISE EXCEPTION 'v2_action_intent_terminal_immutable' USING ERRCODE='55000';
    END IF;
    IF OLD.status = 'PLANNED' AND NEW.status IN ('COMMITTED','SUPERSEDED') THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'v2_action_intent_immutable' USING ERRCODE='55000';
END $v2_guard$
"""
    )
    op.execute(
        "CREATE TRIGGER trg_economic_action_intents_lifecycle "
        "BEFORE INSERT OR UPDATE OR DELETE ON trading.economic_action_intents "
        "FOR EACH ROW EXECUTE FUNCTION trading.v2_guard_action_intent()"
    )


