def _drop_guards() -> None:
    op.execute(
        "DROP TRIGGER IF EXISTS trg_economic_action_intents_lifecycle "
        "ON trading.economic_action_intents"
    )
    op.execute("DROP FUNCTION IF EXISTS trading.v2_guard_action_intent()")
    for table in ("action_set_legs", "action_sets"):
        op.execute(
            f"DROP TRIGGER IF EXISTS trg_{table}_action_set_complete ON trading.{table}"
        )
    op.execute("DROP FUNCTION IF EXISTS trading.v2_check_action_set()")
    op.execute(
        "DROP TRIGGER IF EXISTS trg_trade_decisions_lifecycle ON trading.trade_decisions"
    )
    op.execute("DROP FUNCTION IF EXISTS trading.v2_guard_trade_decision()")
    # 恢复 0021 gate guard
    op.execute("DROP TRIGGER IF EXISTS trg_gate_decisions_semantics ON trading.gate_decisions")
    op.execute("DROP FUNCTION IF EXISTS trading.v2_guard_gate_decision()")
    op.execute(_gate_guard_0021_fn())
    op.execute(
        "CREATE TRIGGER trg_gate_decisions_semantics BEFORE INSERT ON trading.gate_decisions "
        "FOR EACH ROW EXECUTE FUNCTION trading.v2_guard_gate_decision()"
    )
    for table in reversed(_DECISION_TABLES):
        if table.append_only:
            op.execute(
                f"DROP TRIGGER IF EXISTS trg_{table.name}_immutable "
                f"ON {TRADING_SCHEMA}.{table.name}"
            )


_DECISION_INDEXES = (
    "CREATE INDEX ix_trade_decisions_episode ON trading.trade_decisions (episode_id)",
    "CREATE INDEX ix_trade_decisions_submission ON trading.trade_decisions (forecast_submission_id)",
    "CREATE INDEX ix_action_candidates_decision ON trading.action_candidates (trade_decision_id)",
    "CREATE INDEX ix_resolution_cashflows_candidate ON trading.resolution_cashflows (action_candidate_id)",
    "CREATE INDEX ix_action_set_legs_set ON trading.action_set_legs (action_set_id)",
    "CREATE INDEX ix_economic_action_intents_action_set ON trading.economic_action_intents (action_set_id)",
)


def _create_indexes() -> None:
    for statement in _DECISION_INDEXES:
        op.execute(statement)


def _drop_indexes() -> None:
    for statement in _DECISION_INDEXES:
        index_name = statement.split(" ON ")[0].replace("CREATE INDEX ", "").strip()
        op.execute(f"DROP INDEX IF EXISTS {TRADING_SCHEMA}.{index_name}")


def upgrade() -> None:
    for table in _DECISION_TABLES:
        op.execute(table.create_sql)
    _create_indexes()
    _reinforce_existing()
    _create_guards()


def downgrade() -> None:
    _assert_downgrade_safe()
    _drop_guards()
    _unreinforce_existing()
    _drop_indexes()
    for table in reversed(_DECISION_TABLES):
        op.execute(f"DROP TABLE {TRADING_SCHEMA}.{table.name}")
